import os, sys, tempfile, pathlib
from datetime import date, datetime, timezone, timedelta
sys.path.insert(0, os.getcwd())
from app.data.params import make_request, InvalidRequestError
from app.data import cache
naive = datetime(2024, 1, 1); aware = datetime(2024, 1, 1, 23, tzinfo=timezone(timedelta(hours=-3)))
today = date(2025, 1, 1)
for m in (naive, aware):
    for s, e in ((m, date(2024, 1, 2)), (date(2023, 12, 31), m), (m, m)):
        try:
            make_request("BTCUSDT", "1h", s, e, "spot", today); print("NO ERROR", s, e)
        except InvalidRequestError as x: print("InvalidRequestError:", x)
        except Exception as x: print("OTHER", type(x).__name__, x)
print("date ->", make_request("BTCUSDT", "1h", date(2024,1,1), date(2024,1,2), "spot", today))
print("str  ->", make_request("BTCUSDT", "1h", "2024-01-01", "2024-01-02", "spot", today))
for bad in ("2024-1-1", "2024-01-01T00:00"):
    try: make_request("BTCUSDT", "1h", bad, "2024-01-02", "spot", today); print("NO ERROR", bad)
    except InvalidRequestError as x: print("outside, str", repr(bad), "->", x)
with tempfile.TemporaryDirectory() as d:
    d = pathlib.Path(d)
    for kw in ({"start": naive}, {"end": aware}):
        try: cache.clear_cache("BTCUSDT", cache_dir=d, **kw); print("NO ERROR clear", kw)
        except InvalidRequestError as x: print("clear_cache", list(kw), "->", x)
        except Exception as x: print("OTHER", type(x).__name__, x)
    print("clear_cache date/str ->", cache.clear_cache("BTCUSDT", start=date(2024,1,1), end="2024-01-02", cache_dir=d))
EOF
